    createSavedField: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "name": "North 80",
                 *       "field_id": "csb2025_1900001",
                 *       "geometry": {
                 *         "type": "Polygon",
                 *         "coordinates": [
                 *           [
                 *             [
                 *               -93.7,
                 *               41.98
                 *             ],
                 *             [
                 *               -93.69,
                 *               41.98
                 *             ],
                 *             [
                 *               -93.69,
                 *               41.99
                 *             ],
                 *             [
                 *               -93.7,
                 *               41.99
                 *             ],
                 *             [
                 *               -93.7,
                 *               41.98
                 *             ]
                 *           ]
                 *         ]
                 *       },
                 *       "crop_history": [
                 *         {
                 *           "year": 2025,
                 *           "crop": "Corn"
                 *         },
                 *         {
                 *           "year": 2024,
                 *           "crop": "Soybeans"
                 *         }
                 *       ]
                 *     }
                 */
                "application/json": components["schemas"]["SavedFieldCreate"];
            };
        };
        responses: {
            /** @description Saved */
            201: {
                headers: {
                    /** @description `/v1/me/fields/{id}` */
                    Location?: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["SavedField"];
                };
            };
            401: components["responses"]["Unauthorized"];
            /** @description `FIELD_LIMIT_REACHED`. `details.limit` is the per-user cap. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description `VALIDATION_ERROR` (bad name, geometry or crop history) or `OUTSIDE_COVERAGE` */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
        };
    };
